"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[4139],{4698(e){e.exports=JSON.parse('{"tag":{"label":"Heuristics","permalink":"/concepts/tags/heuristics","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"state-space-search-and-optimization/branch-and-bound","title":"Branch and Bound","description":"Branch and bound (B&B) is the last design technique of the course. Like backtracking, it searches an implicit tree of states: nodes represent states of the problem, edges represent valid changes, and solving the problem means finding a node (or a path) in that tree. The difference is the order in which the tree is explored, and that single change makes it suitable for different problems.","permalink":"/concepts/state-space-search-and-optimization/branch-and-bound"},{"id":"state-space-search-and-optimization/branch-and-bound-examples","title":"Branch and Bound: Classic Problems","description":"This lesson applies the general scheme of branch and bound to several problems. In each one, the work consists of answering the same three questions:","permalink":"/concepts/state-space-search-and-optimization/branch-and-bound-examples"},{"id":"algorithm-design-paradigms/greedy-algorithms","title":"Greedy Algorithms","description":"Many problems ask not just for a solution, but for the best one they build the solution step by step and, at each step, they take the choice that looks best right now, without ever reconsidering it.","permalink":"/concepts/algorithm-design-paradigms/greedy-algorithms"}],"unlisted":false}}')}}]);